--    Postgres grants EXECUTE on new functions to PUBLIC, so revoking from anon alone changes
--    nothing: revoke from PUBLIC and hand it back only to the API's service role.
revoke execute on function public."match_kb"(query_text text, k integer, kinds text[]) from public, anon, authenticated;
grant execute on function public."match_kb"(query_text text, k integer, kinds text[]) to service_role;

-- 5. Stale blanket read policies for authenticated (inert once grants are gone).
drop policy if exists "app_settings_read" on public."app_settings";
drop policy if exists "ar_ageing_read" on public."ar_ageing";
drop policy if exists "catalog_items_read" on public."catalog_items";
drop policy if exists "customer_contacts_read" on public."customer_contacts";
drop policy if exists "salesman_targets_read" on public."salesman_targets";
drop policy if exists "stock_balance_read" on public."stock_balance";
drop policy if exists "user_roles_read" on public."user_roles";

-- 6. Stop the default ACL from re-granting future objects. Only the defaults owned by
--    postgres can be changed from this connection; objects created by supabase_admin
--    (extensions) keep theirs, which is why audit_grants.py must stay in the release check.
alter default privileges for role postgres in schema public revoke all on tables from anon, authenticated;
alter default privileges for role postgres in schema public revoke all on sequences from anon, authenticated;
alter default privileges for role postgres in schema public revoke all on functions from anon, authenticated;

-- 7. The one thing the publishable key may still touch: an empty ping table for the
--    GitHub keepalive job (.github/workflows/keepalive.yml). RLS on, no policy -> [] + HTTP 200.
create table if not exists public.keepalive_ping (id smallint primary key);
alter table public.keepalive_ping enable row level security;
revoke all on table public.keepalive_ping from anon, authenticated;
grant select on table public.keepalive_ping to anon;

-- 8. Verification: fails the transaction if anything is still exposed.
do $$
declare
  leftover int;
  norls int;
  pol int;
begin
  select count(*) into leftover
  from information_schema.role_table_grants
  where table_schema = 'public' and grantee in ('anon', 'authenticated')
    and not (table_name = 'keepalive_ping' and grantee = 'anon' and privilege_type = 'SELECT');
  if leftover > 0 then
    raise exception 'grant lockdown FAILED: % anon/authenticated grants remain on public', leftover;
  end if;
  select count(*) into norls from pg_tables where schemaname = 'public' and not rowsecurity;
  if norls > 0 then
    raise exception 'grant lockdown FAILED: % public tables without RLS', norls;
  end if;
  select count(*) into pol from pg_policies where schemaname = 'public' and 'authenticated' = any(roles);
  if pol > 0 then
    raise exception 'grant lockdown FAILED: % policies still target authenticated', pol;
  end if;
  raise notice 'grant lockdown: verified -- public schema is closed to anon/authenticated (keepalive_ping SELECT only)';
end $$;
